  ctypes.set_errno(0);fd=libc.openat(directory,os.fsencode(word),os.O_RDONLY|os.O_NOFOLLOW);error=ctypes.get_errno()
  if fd<0:
   if error!=errno.ENOENT:raise OSError(error,'openat failed')
   rows.append({'name':word,'errno':error,'bytes':None,'sha256':None})
  else:
   try:
    data=b''
