import hashlib,os,pathlib,stat
def inspect(root):
 root=pathlib.Path(root)
 if not root.is_absolute()or root.is_symlink()or not root.is_dir()or root.stat().st_uid!=os.getuid():raise ValueError('owned absolute flat directory')
 rows=[]
 for path in root.iterdir():
  info=path.lstat()
  if not stat.S_ISREG(info.st_mode)or info.st_uid!=os.getuid()or info.st_size>4096:raise ValueError('owned regular files, each <=4096 bytes')
  path.name.encode('utf8');rows.append({'name':path.name,'bytes':info.st_size,'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
 if len(rows)>16:raise ValueError('at most16 files')
 return sorted(rows,key=lambda row:row['name'].encode('utf8'))

