import json,os,pathlib,shutil,sys,tempfile
import context
MODES=('direct','quoted','shell','application')
def run(root,result,probe):
 root=pathlib.Path(root);result=pathlib.Path(result);probe=pathlib.Path(probe);before=context.inspect(root)
 if not result.is_absolute()or result.exists()or result.is_symlink()or not result.parent.is_dir()or result.parent.stat().st_uid!=os.getuid()or not probe.is_absolute()or not probe.is_file()or probe.is_symlink():raise ValueError('new absolute result and approved probe required')
 if result.parent==root or root in result.parents:raise ValueError('result outside source')
 with tempfile.TemporaryDirectory(dir=result.parent,prefix='.boundary-')as directory:
  stage=pathlib.Path(directory)/'complete';stage.mkdir()
  (stage/'inventory.json').write_text(json.dumps(before,ensure_ascii=False))
  for mode in MODES:
   base=[sys.executable,'-B',str(probe),str(root),str(stage/mode),mode]
   if mode=='application':words=[row['name']for row in before if not row['name'].startswith('.')and row['name'].endswith('.log')];argv=base+words
   elif mode=='direct':argv=base+['*.log']
   else:
    command='unset GLOBIGNORE; shopt -u dotglob failglob nocaseglob; shopt -s nullglob; cd -- "$ROOT" || exit; '
    command+='exec "$PY" -B "$PROBE" "$ROOT" "$OUT" "$MODE" '+('"$PATTERN"'if mode=='quoted'else'$PATTERN')
    argv=['/usr/bin/bash','--noprofile','--norc','-c',command]
   env=dict(os.environ,LC_ALL='C.UTF-8',ROOT=str(root),OUT=str(stage/mode),MODE=mode,PATTERN='*.log',PY=sys.executable,PROBE=str(probe));env.pop('BASH_ENV',None);env.pop('ENV',None)
   pid=os.fork()
   if pid==0:
    try:os.execve(argv[0],argv,env)
    except BaseException:os._exit(127)
   try:
    _,status=os.waitpid(pid,0)
   except BaseException:
    import signal
    try:os.kill(pid,signal.SIGKILL)
    except ProcessLookupError:pass
    os.waitpid(pid,0);raise
   if os.waitstatus_to_exitcode(status)!=0:raise ValueError('native probe failed')
  if context.inspect(root)!=before:raise ValueError('source changed')
  os.rename(stage,result)
 return str(result)

