import errno,hashlib,json,pathlib
import context
def inspect(root,result):
 root=pathlib.Path(root);result=pathlib.Path(result);inventory=context.inspect(root)
 try:
  if json.loads((result/'inventory.json').read_text())!=inventory:raise ValueError('source inventory changed')
  names=[row['name']for row in inventory];matches=[name for name in names if not name.startswith('.')and name.endswith('.log')];by_name={row['name']:row for row in inventory};evidence={}
  for mode in ('direct','quoted','shell','application'):
   expected=['*.log']if mode in ('direct','quoted')else matches
   raw=(result/mode/'argv.nul').read_bytes();wanted=b''.join(name.encode('utf8')+b'\0'for name in expected)
   if raw!=wanted:raise ValueError('actual argv differs')
   rows=json.loads((result/mode/'opens.json').read_text());wanted_rows=[]
   for name in expected:
    row=by_name.get(name);wanted_rows.append({'name':name,'errno':errno.ENOENT if row is None else 0,'bytes':None if row is None else row['bytes'],'sha256':None if row is None else row['sha256']})
   if json.dumps(rows,sort_keys=True)!=json.dumps(wanted_rows,sort_keys=True):raise ValueError('literal kernel openat evidence differs')
   evidence[mode]={'argv':expected,'opens':rows}
 except(OSError,UnicodeError,KeyError,TypeError,json.JSONDecodeError)as error:raise ValueError('invalid evidence')from error
 return {'schema':1,'verified':True,'source_files':len(inventory),'evidence':evidence,'conclusion':'shell and application expansion are user-space; openat resolves each literal pathname'}

