 def trace(request,pid,address=0,data=0):
  answer=libc.ptrace(request,pid,ctypes.c_void_p(address),ctypes.c_void_p(data))
  if answer==-1:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR owned child ptrace errno'+str(ctypes.get_errno()))
  return answer
 child=os.fork()
