import socket
def exchange(host,port,payload):
 if type(payload) is not bytes or len(payload)>1024:raise ValueError('bounded bytes required')
 with socket.create_connection((host,port),timeout=2) as sock:
  sock.sendall(payload);sock.shutdown(socket.SHUT_WR);parts=[];size=0
  while True:
   block=sock.recv(1024)
   if not block:break
   size+=len(block)
   if size>4096:raise ValueError('response too large')
   parts.append(block)
  return b''.join(parts)

