def snapshot(root,version,tags=()):
 root=pathlib.Path(root)
 if not root.is_absolute() or root.is_symlink() or not root.is_dir() or root.stat().st_uid!=os.getuid():raise ValueError('owned absolute source root')
 if not isinstance(version,str)or not version or any(c.isspace()for c in version):raise ValueError('version token')
 if any(not isinstance(t,str)or not t or any(c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'for c in t)for t in tags):raise ValueError('build tags')
 files={}
 for path in sorted(root.rglob('*')):
  if path.is_symlink():raise ValueError('source links not approved')
  if path.is_file()and(path.suffix in ('.go','.mod','.sum')):files[path.relative_to(root).as_posix()]=hashlib.sha256(path.read_bytes()).hexdigest()
 if 'go.mod'not in files:raise ValueError('go.mod required')
