  if replacement:
   directory=replacement.get('Dir')
   if not directory or not pathlib.Path(directory).resolve().is_relative_to(root.resolve()):raise ValueError('outside-root replace is not within this lock scope')
  elif not module.get('Main'):raise ValueError('downloaded dependencies need a separately approved content lock')
