 env=json.loads(subprocess.check_output([str(go),'env','-json','GOOS','GOARCH','GOVERSION','GOEXPERIMENT','GOAMD64'],text=True,timeout=5))
 return {'schema':1,'source_sha256':files,'go_sha256':hashlib.sha256(go.read_bytes()).hexdigest(),'toolchain':env,'cgo_enabled':'0','cgo_scope':'pure-Go only; CGO builds require separate C compiler/system-library lock and validation','tags':sorted(set(tags)),'version':version,'flags':['-trimpath','-buildvcs=false'],'module_policy':{'GOPROXY':'off','GOSUMDB':'off','GOTOOLCHAIN':'local','GOFLAGS':'','GOWORK':'off'}}

