import math
def evaluate(previous,current):
 if previous['instance']!=current['instance']:raise ValueError('same series instance required')
 if any(type(row['at'])not in(int,float)or not math.isfinite(row['at'])for row in (previous,current)):raise ValueError('finite numeric timestamps required')
 elapsed=current['at']-previous['at']
 if elapsed<=0 or type(previous['value']) is not int or type(current['value']) is not int or min(previous['value'],current['value'])<0:raise ValueError('increasing timestamps and cumulative nonnegative counters required')
 reset=previous['boot_id']!=current['boot_id'] or current['value']<previous['value']
 delta=None if reset else current['value']-previous['value']
 return {'counter_reset':reset,'delta':delta,'rate':None if reset else delta/elapsed,'recovery_confirmed':False,'status':'insufficient_post_reset_evidence' if reset else 'observed'}

