package practice
import("context";"errors";"net/http";"sync";"time")
type Result struct{Target string;Status int;Elapsed time.Duration;Error string}
func Inspect(ctx context.Context,targets []string,workers int,timeout time.Duration)([]Result,error){
 if ctx==nil||workers<1||workers>64||len(targets)>64||timeout<=0{return nil,errors.New("bounded positive workers, targets and timeout required")}
 transport:=&http.Transport{};defer transport.CloseIdleConnections();client:=&http.Client{Transport:transport,Timeout:timeout}
 results:=make([]Result,len(targets));jobs:=make(chan int,len(targets));for i:=range targets{jobs<-i};close(jobs)
 var group sync.WaitGroup
 for worker:=0;worker<workers;worker++{group.Add(1);go func(){defer group.Done();for index:=range jobs{results[index]=inspectOne(ctx,client,targets[index])}}()};group.Wait();return results,nil
}

