import("context";"net/http";"time";"io";"errors")
func inspectOne(ctx context.Context,client *http.Client,target string)Result{
 start:=time.Now();result:=Result{Target:target};defer func(){}()
 request,err:=http.NewRequestWithContext(ctx,http.MethodGet,target,nil)
 if err!=nil{result.Error=err.Error();result.Elapsed=time.Since(start);return result}
 reply,err:=client.Do(request)
 if err!=nil{result.Error=err.Error();result.Elapsed=time.Since(start);return result}
 result.Status=reply.StatusCode
 count,readError:=io.Copy(io.Discard,io.LimitReader(reply.Body,65537));closeError:=reply.Body.Close()
 if count>65536{readError=errors.New("body exceeds inspection bound")};if readError!=nil{result.Error=readError.Error()}else if closeError!=nil{result.Error=closeError.Error()}
 result.Elapsed=time.Since(start);return result
}

