import pathlib,os,re,gzip,io,hashlib,shlex
def catalog(root):
 root=pathlib.Path(root)
 if not root.is_absolute()or root.is_symlink()or not root.is_dir()or root.stat().st_uid!=os.getuid():raise ValueError('owned absolute manual root')
 rows=[]
 for section in range(1,10):
  directory=root/('man'+str(section))
  if directory.is_symlink():raise ValueError('no links')
  if not directory.exists():continue
  if not directory.is_dir():raise ValueError('manual section directory required')
  for p in sorted(directory.iterdir()):
   pattern=r'([A-Za-z0-9_.+-]+)\.'+str(section)+r'(\.gz)?'
   match=re.fullmatch(pattern,p.name)
   if not match or match[1]in ('.','..')or p.is_symlink()or not p.is_file()or p.stat().st_uid!=os.getuid()or p.stat().st_size>65536:raise ValueError('approved direct roff pages only')
   raw=p.read_bytes()
   text=gzip.GzipFile(fileobj=io.BytesIO(raw)).read(65537)if p.name.endswith('.gz')else raw
   if len(text)>65536:raise ValueError('page limit')
   lines=text.decode('utf8').splitlines();headers=[shlex.split(line)for line in lines if re.match(r'^\.TH[ \t]+',line)]
   if len(headers)!=1 or len(headers[0])<3 or headers[0][2]!=str(section):raise ValueError('TH section differs')
   rows.append({'name':match[1],'section':section,'path':str(p),'sha256':hashlib.sha256(raw).hexdigest()})
 return sorted(rows,key=lambda row:(row['name'],row['section'],row['path']))

