import pathlib,os,subprocess,re,hashlib
def identity(pid):
 if type(pid)is not int or pid<=0:raise ValueError('positive PID')
 root=pathlib.Path('/proc')/str(pid)
 if root.stat().st_uid!=os.geteuid():raise ValueError('not owned by effective UID')
 status=(root/'stat').read_text();fields=status[status.rfind(')')+2:].split();cmd=(root/'cmdline').read_bytes();cgroup=(root/'cgroup').read_text()
 return {'pid':pid,'uid':root.stat().st_uid,'ppid':int(fields[1]),'start_ticks':int(fields[19]),'cmdline':[v.decode('utf8',errors='replace')for v in cmd.rstrip(bytes([0])).split(bytes([0]))],'cmdline_sha256':hashlib.sha256(cmd).hexdigest(),'exe':os.readlink(root/'exe'),'netns':os.readlink(root/'ns/net'),'cgroup':cgroup}
def lookup(port):
 if type(port)is not int or not 1<=port<=65535:raise ValueError('valid TCP port')
 p=subprocess.run(['ss','-H','-ltnp','sport = :'+str(port)],capture_output=True,text=True,timeout=3,check=True)
 rows=[line for line in p.stdout.splitlines()if line.strip()];pids={int(value)for value in re.findall(r'pid=(\d+)',p.stdout)}
 if not rows or any(not re.search(r'pid=(\d+)',line)for line in rows)or len(pids)!=1:raise ValueError('unique visible listener PID required; multiple sockets of that PID are legal')
 found=identity(pids.pop())
 if found['netns']!=os.readlink('/proc/self/ns/net'):raise ValueError('same network namespace required')
 return {**found,'port':port,'socket_evidence':p.stdout,'scope':'same-netns TCP only; manager ownership requires explicit evidence'}

