import os,signal,select
from lookup import identity,lookup
def stop(observed,approval,deadline=1.0):
 keys=('pid','uid','ppid','start_ticks','cmdline_sha256','exe','netns','cgroup')
 if type(deadline)not in (float,int)or not 0<deadline<=3:raise ValueError('bounded graceful wait')
 if set(approval)!=set(keys)|{'port'}or any(observed.get(k)!=approval[k]for k in (*keys,'port')):raise ValueError('observation approval mismatch')
 if approval['uid']!=os.geteuid()or approval['ppid']!=os.getpid()or any(v in approval['cgroup']for v in ('.service','.scope','docker','kubepods','containerd')):raise ValueError('only own standalone direct child')
 current=lookup(approval['port'])
