package debit

import (
 "context"
 "database/sql"
 "errors"
 "fmt"
 "strings"
 mysql "github.com/go-sql-driver/mysql"
)

type Request struct { ID string; Account int64; Amount int64 }
type Result struct { State string; Request Request; Balance int64 }

func Debit(ctx context.Context, db *sql.DB, request Request) (Result,error) {
 result:=Result{State:"rejected",Request:request}
 if strings.TrimSpace(request.ID)=="" || len(request.ID)>64 || request.Account<=0 || request.Amount<=0 { return result,errors.New("invalid request") }
 tx,err:=db.BeginTx(ctx,nil)
 if err!=nil { result.State="rolled_back";return result,err }
 defer tx.Rollback()
 result.State="rolled_back"
 var balance int64
 if err=tx.QueryRowContext(ctx,"SELECT balance FROM accounts WHERE id=? FOR UPDATE",request.Account).Scan(&balance);err!=nil{return result,err}
 var prior Request;var previousBalance int64
 err=tx.QueryRowContext(ctx,"SELECT operation_id,account_id,amount,result_balance FROM operations WHERE operation_id=?",request.ID).Scan(&prior.ID,&prior.Account,&prior.Amount,&previousBalance)
 if err==nil {
  if prior!=request {result.State="rejected";return result,errors.New("operation id payload mismatch")}
  return Result{State:"committed",Request:prior,Balance:previousBalance},nil
 }
 if !errors.Is(err,sql.ErrNoRows){return result,err}
 if balance<request.Amount{result.State="rejected";return result,errors.New("insufficient balance")}
 result.Balance=balance-request.Amount
 if _,err=tx.ExecContext(ctx,"INSERT INTO operations(operation_id,account_id,amount,result_balance) VALUES (?,?,?,?)",request.ID,request.Account,request.Amount,result.Balance);err!=nil{
  // Two different account locks may race for the same global operation id.
  // The unique ledger key still arbitrates; its duplicate is a rejected payload.
  var duplicate *mysql.MySQLError
  if errors.As(err,&duplicate)&&duplicate.Number==1062{result.State="rejected"}
  return result,err
 }
 if _,err=tx.ExecContext(ctx,"UPDATE accounts SET balance=balance-? WHERE id=?",request.Amount,request.Account);err!=nil{return result,err}
 if err=tx.Commit();err!=nil {result.State="unknown";return result,fmt.Errorf("commit outcome unknown: %w",err)}
 result.State="committed"
 return result,nil
}

