import pathlib,hashlib,json,proxy_view

def build(snapshot_path,expected,destination):
 source=pathlib.Path(snapshot_path);raw=source.read_bytes()
 views={kind:proxy_view.read(source,kind)for kind in ('clusters','listeners','routes')}
 clusters=[row['name']for row in views['clusters']]
 if len(set(clusters))!=len(clusters):raise ValueError('duplicate cluster')
 routes={}
 for row in views['routes']:
  name=row['name']
  if name in routes:raise ValueError('duplicate route configuration')
  targets=set()
  for host in row.get('virtualHosts',[]):
   for item in host.get('routes',[]):
    action=item.get('route',{})
    if 'cluster'in action:targets.add(action['cluster'])
    for target in action.get('weightedClusters',{}).get('clusters',[]):targets.add(target['name'])
  if not targets.issubset(set(clusters)):raise ValueError('dangling cluster reference')
  routes[name]=sorted(targets)
 listeners={}
 for row in views['listeners']:
  name=row['name']
  if name in listeners:raise ValueError('duplicate listener')
  linked=set()
  for chain in row.get('filterChains',[]):
   for item in chain.get('filters',[]):
    if item['name']=='envoy.filters.network.http_connection_manager':
     config=item['typedConfig']
     if 'routeConfig'in config:linked.add(config['routeConfig']['name'])
  if not linked.issubset(set(routes)):raise ValueError('dangling route reference')
  listeners[name]=sorted(linked)
 actual={'clusters':sorted(clusters),'route_targets':routes,'listener_routes':listeners}
 if actual!=expected:raise ValueError('approved effective reference graph differs')
 result={'snapshot_sha256':hashlib.sha256(raw).hexdigest(),**actual,'scope':'offline-effective-config-only','control_plane_sync_proven':False,'production_reachability_proven':False}
 root=pathlib.Path(destination);root.mkdir()
 (root/'snapshot.json').write_bytes(raw)
 for kind,data in views.items():(root/(kind+'.json')).write_text(json.dumps(data,sort_keys=True))
 (root/'effective-report.json').write_text(json.dumps(result,sort_keys=True))
 return result

