def run(base_url,requests,concurrency):
    endpoint=urllib.parse.urlsplit(base_url)
    if endpoint.scheme!='http'or endpoint.hostname!='127.0.0.1'or not endpoint.port:raise ValueError('owned explicit loopback HTTP endpoint')
    if type(concurrency)is not int or not 1<=concurrency<=4 or not 1<=len(requests)<=32:raise ValueError('bounded ordinary local workload')
