import decimal,datetime

def adapt(event):
    if not isinstance(event,dict): raise ValueError('object required')
    for key in ('event_id','occurred_at'):
        if not isinstance(event.get(key),str) or not event[key].strip(): raise ValueError(key)
    try:
        stamp=datetime.datetime.fromisoformat(event['occurred_at'].replace('Z','+00:00'))
        if stamp.tzinfo is None: raise ValueError('timezone')
    except (ValueError,TypeError): raise ValueError('occurred_at')
    if event.get('type')!='payment.recorded': raise ValueError('type')
    version=event.get('payload_version');p=event.get('payload')
    if type(version)is not int or version not in (1,2,3) or not isinstance(p,dict): raise ValueError('version/payload')
    customer=p.get('client_id'if version==1 else'customer_id')
    if not isinstance(customer,str) or not customer.strip(): raise ValueError('customer')
    if p.get('currency')!='USD': raise ValueError('currency')
    status=p.get('status')
    if status not in ({'paid','cancelled'}if version<3 else{'paid','cancelled','refunded'}): raise ValueError('status')
    if version==2:
        value=p.get('amount')
        if not isinstance(value,str): raise ValueError('decimal string amount')
        try:
            amount=decimal.Decimal(value)*100
            if not amount.is_finite() or amount!=amount.to_integral_value(): raise ValueError('minor unit precision')
            cents=int(amount)
        except decimal.InvalidOperation: raise ValueError('amount')
    else:
        cents=p.get('amount_cents'if version==1 else'minor_units')
        if type(cents)is not int: raise ValueError('minor units')
    if cents<0 or cents>10**12: raise ValueError('amount range')
    return {'event_id':event['event_id'],'occurred_at':event['occurred_at'],'customer_id':customer,'currency':'USD','amount_cents':cents,'status':status,'source_version':version}

