import pathlib,json,hashlib,sqlite3
from adapter import adapt

def run(source,database,mode='replay'):
    if mode not in ('replay','live'): raise ValueError('mode')
    data=pathlib.Path(source).read_bytes();counts={'accepted':0,'duplicate':0,'quarantined':0,'effects_created':0}
    with closing(sqlite3.connect(database))as db,db:
        db.executescript('CREATE TABLE IF NOT EXISTS originals(hash TEXT PRIMARY KEY,raw BLOB NOT NULL);CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,hash TEXT NOT NULL,normalized TEXT NOT NULL);CREATE TABLE IF NOT EXISTS quarantine(hash TEXT PRIMARY KEY,reason TEXT NOT NULL);CREATE TABLE IF NOT EXISTS effects(id TEXT PRIMARY KEY,amount_cents INTEGER NOT NULL);')
        for raw in data.splitlines(keepends=True):
            digest=hashlib.sha256(raw).hexdigest();db.execute('INSERT OR IGNORE INTO originals VALUES(?,?)',(digest,raw))
            try:
                e=adapt(json.loads(raw));existing=db.execute('SELECT hash FROM events WHERE id=?',(e['event_id'],)).fetchone()
                if existing and existing[0]!=digest: raise ValueError('event-id payload conflict')
                if existing: counts['duplicate']+=1
                else:
                    db.execute('INSERT INTO events VALUES(?,?,?)',(e['event_id'],digest,json.dumps(e,sort_keys=True)));counts['accepted']+=1
                if mode=='live'and e['status']=='paid':
                    cur=db.execute('INSERT OR IGNORE INTO effects VALUES(?,?)',(e['event_id'],e['amount_cents']));counts['effects_created']+=cur.rowcount
            except (ValueError,TypeError,KeyError,UnicodeDecodeError)as exc:
                db.execute('INSERT OR IGNORE INTO quarantine VALUES(?,?)',(digest,str(exc)));counts['quarantined']+=1
    return {'mode':mode,'input_sha256':hashlib.sha256(data).hexdigest(),**counts}

