FD_ROOT=None

def owned_fds():
    result=[]
    for entry in pathlib.Path('/proc/self/fd').iterdir():
        try:target=os.readlink(entry)
        except FileNotFoundError:continue
        if FD_ROOT is not None and target.startswith(str(FD_ROOT)+os.sep):result.append((entry.name,target))
    return set(result)

def fd_guard(function):
    def checked(*args,**kwargs):
        before=owned_fds()
        try:return function(*args,**kwargs)
        finally:
            after=owned_fds()
            assert after<=before,'owned file/SQLite descriptors remain open after operation: '+repr(sorted(after-before))
    return checked

replay.run=fd_guard(replay.run)
report.summarize=fd_guard(report.summarize)
report.publish=fd_guard(report.publish)

