from contextlib import closing
import sqlite3
class Services:
    def __init__(self,path):self.path=path
    def payment_status(self,key):
        with closing(sqlite3.connect(self.path))as db,db:
            if not db.execute("SELECT value FROM control WHERE key='query_available'").fetchone()[0]:raise ConnectionError('controlled local query unavailable')
            row=db.execute('SELECT status FROM ledger WHERE payment_key=?',(key,)).fetchone()
        if row is None:raise KeyError(key)
        return row[0]
    def release(self,key,reservation):
        with closing(sqlite3.connect(self.path))as db,db:
            if not db.execute("SELECT value FROM control WHERE key='release_available'").fetchone()[0]:raise ConnectionError('controlled local release unavailable')
            row=db.execute('SELECT quantity,released,release_key FROM reservations WHERE key=?',(reservation,)).fetchone()
            if row is None:raise KeyError(reservation)
            if row[2]!=key:raise ValueError('stable approved release key required')
            db.execute('INSERT INTO calls(release_key,reservation)VALUES(?,?)',(key,reservation))
            lose_ack=db.execute("SELECT value FROM control WHERE key='release_ack_timeout_once'").fetchone()[0]
            if lose_ack:db.execute("UPDATE control SET value=0 WHERE key='release_ack_timeout_once'")
            if not row[1]:
                db.execute('UPDATE reservations SET released=1 WHERE key=?',(reservation,));db.execute('UPDATE inventory SET free_units=free_units+?',(row[0],));db.execute('INSERT INTO receipts VALUES(?,?)',(key,reservation))
        if lose_ack:raise TimeoutError('controlled local release acknowledgment lost after commit')
    def inventory_snapshot(self):
        with closing(sqlite3.connect(self.path))as db,db:
            initial,free=db.execute('SELECT initial_units,free_units FROM inventory').fetchone();reserved=db.execute('SELECT COALESCE(SUM(quantity),0)FROM reservations WHERE released=0').fetchone()[0];receipts=[list(x)for x in db.execute('SELECT key,reservation FROM receipts ORDER BY key')];calls=[list(x)for x in db.execute('SELECT release_key,reservation FROM calls ORDER BY id')];reservations=[{'key':x[0],'quantity':x[1],'released':bool(x[2]),'release_key':x[3]}for x in db.execute('SELECT key,quantity,released,release_key FROM reservations ORDER BY key')]
        return {'initial_units':initial,'free_units':free,'reserved_units':reserved,'release_receipts':receipts,'release_calls':calls,'reservations':reservations}
    def ledger_snapshot(self):
        with closing(sqlite3.connect(self.path))as db,db:return [{'payment_key':x[0],'status':x[1],'amount_cents':x[2]}for x in db.execute('SELECT payment_key,status,amount_cents FROM ledger ORDER BY payment_key')]

