import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;

public final class HelloServlet extends HttpServlet {
    private static String quote(String text) {
        return "\"" + text.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
    }
    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String requestId = request.getHeader("X-Request-ID");
        response.setContentType("application/json");
        response.setCharacterEncoding("UTF-8");
        if (requestId == null || !requestId.matches("[A-Za-z0-9_-]{1,80}")) {
            response.setStatus(400);
            response.getWriter().print("{\"error\":\"request_id_required\"}");
            return;
        }
        response.getWriter().print("{\"request_id\":" + quote(requestId)
            + ",\"pid\":" + ProcessHandle.current().pid()
            + ",\"java_version\":" + quote(System.getProperty("java.version"))
            + ",\"container\":" + quote(getServletContext().getServerInfo()) + "}");
    }
}

