 "sync"
 "time"
)

type backend struct {
 mu sync.Mutex
 file *os.File
 attempts map[string]int
 active map[string]int
 mutations map[string]int
}

func (b *backend) eventLocked(kind, id, mode string, attempt int, request *http.Request) {
 row:=map[string]interface{}{"event":kind,"id":id,"mode":mode,"attempt":attempt,"at_ns":time.Now().UnixNano(),"active":b.active[id],"mutations":b.mutations[id],"method":request.Method,"protocol":request.Proto,"remote":request.RemoteAddr,"envoy_attempt":request.Header.Get("x-envoy-attempt-count")}
 if err:=json.NewEncoder(b.file).Encode(row);err!=nil {panic(err)}
}

func (b *backend) ServeHTTP(writer http.ResponseWriter,request *http.Request) {
 id:=request.URL.Query().Get("id")
 if id==""||len(id)>80 {http.Error(writer,"bounded id required",400);return}
 mode:="cooperative"
 if strings.HasPrefix(request.URL.Path,"/noncooperative/") {mode="noncooperative"}
 if strings.HasPrefix(request.URL.Path,"/mutation/") {mode="mutation"}
 b.mu.Lock()
 b.attempts[id]++
 attempt:=b.attempts[id]
 b.active[id]++
 if mode=="mutation" {b.mutations[id]++}
 b.eventLocked("start",id,mode,attempt,request)
 b.mu.Unlock()
 defer func(){b.mu.Lock();b.active[id]--;b.eventLocked("leave",id,mode,attempt,request);b.mu.Unlock()}()
 if mode=="mutation" {
  b.mu.Lock();b.eventLocked("mutation_applied",id,mode,attempt,request);b.mu.Unlock()
  http.Error(writer,"declared non-idempotent teaching mutation completed before 503",503)
  return
 }
 duration:=600*time.Millisecond
 if attempt>1&&request.URL.Query().Get("all_slow")!="1" {duration=25*time.Millisecond}
 timer:=time.NewTimer(duration);defer timer.Stop()
 finished:=make(chan struct{});observed:=make(chan struct{})
 var cancellation sync.Once
 recordCancellation:=func(){cancellation.Do(func(){b.mu.Lock();b.eventLocked("cancel_received",id,mode,attempt,request);b.mu.Unlock()})}
 go func(){
  defer close(observed)
  select {
  case <-request.Context().Done():
   recordCancellation()
  case <-finished:
  }
 }()
 cancelled:=false
 if mode=="cooperative" {
  select {
  case <-request.Context().Done():cancelled=true
  case <-timer.C:
  }
 } else {<-timer.C}
 close(finished);<-observed
 if cancelled {
  recordCancellation()
  b.mu.Lock();b.eventLocked("work_aborted",id,mode,attempt,request);b.mu.Unlock()
  return
 }
 b.mu.Lock();b.eventLocked("work_completed",id,mode,attempt,request);b.mu.Unlock()
 digest:=sha256.Sum256([]byte(id))
 writer.Header().Set("Content-Type","application/json")
 json.NewEncoder(writer).Encode(map[string]interface{}{"id":id,"safe_read":true,"result_sha256":hex.EncodeToString(digest[:]),"attempt":attempt})
}

func main() {
 if os.Getuid()!=1000 {panic("explicit student UID1000 required")}
 if len(os.Args)!=3 {panic("event path and port required")}
 port,err:=strconv.Atoi(os.Args[2]);if err!=nil {panic(err)}
 log,err:=os.OpenFile(os.Args[1],os.O_CREATE|os.O_EXCL|os.O_WRONLY,0600);if err!=nil {panic(err)};defer log.Close()
