import jakarta.servlet.http.*;
import jakarta.servlet.ServletException;
import java.io.*;
import java.nio.file.*;
import java.sql.*;
import java.lang.management.*;
import java.util.concurrent.*;
import javax.management.*;
import org.apache.tomcat.jdbc.pool.DataSource;
import org.apache.tomcat.jdbc.pool.PoolProperties;

public final class WorkServlet extends HttpServlet {
    private DataSource source;
    private ScheduledExecutorService sampler;
    private String serverVersion;
    private long begin;
    @Override public void init() throws ServletException {
        try {
            PoolProperties properties=new PoolProperties();
            properties.setUrl(System.getProperty("opsforge.jdbc.url"));
            properties.setDriverClassName("com.mysql.cj.jdbc.Driver");
            properties.setUsername("root"); properties.setPassword("");
            properties.setMaxActive(Integer.parseInt(System.getProperty("opsforge.pool.maxActive")));
            properties.setMaxWait(Integer.parseInt(System.getProperty("opsforge.pool.maxWait")));
            properties.setInitialSize(0); properties.setMinIdle(0); properties.setMaxIdle(properties.getMaxActive());
            source=new DataSource(properties);
            try(Connection connection=source.getConnection();Statement statement=connection.createStatement();ResultSet result=statement.executeQuery("SELECT VERSION()")) {
                if(!result.next()) throw new SQLException("server version missing"); serverVersion=result.getString(1);
            }
            begin=System.nanoTime(); sampler=Executors.newSingleThreadScheduledExecutor();
            sampler.scheduleAtFixedRate(this::sample,0,10,TimeUnit.MILLISECONDS);
        } catch(Exception error) { throw new ServletException(error); }
    }
    private void sample() {
        try {
            MBeanServer beans=ManagementFactory.getPlatformMBeanServer();
            ObjectName executor=new ObjectName("Catalina:type=Executor,name=owned");
            long gcCount=0,gcMillis=0;
            for(GarbageCollectorMXBean bean:ManagementFactory.getGarbageCollectorMXBeans()) {
                gcCount+=Math.max(0,bean.getCollectionCount()); gcMillis+=Math.max(0,bean.getCollectionTime());
            }
            MemoryUsage heap=ManagementFactory.getMemoryMXBean().getHeapMemoryUsage();
            String line="{\"elapsed_ms\":"+(System.nanoTime()-begin)/1e6
                +",\"executor_active\":"+beans.getAttribute(executor,"activeCount")
                +",\"executor_queue\":"+beans.getAttribute(executor,"queueSize")
                +",\"executor_max_threads\":"+beans.getAttribute(executor,"maxThreads")
                +",\"pool_active\":"+source.getActive()+",\"pool_waiting\":"+source.getWaitCount()
                +",\"pool_max_active\":"+source.getMaxActive()+",\"pool_max_wait\":"+source.getMaxWait()
                +",\"heap_used\":"+heap.getUsed()+",\"heap_max\":"+heap.getMax()
                +",\"gc_count_cumulative\":"+gcCount+",\"gc_time_ms_cumulative\":"+gcMillis+"}\n";
            Files.writeString(Path.of(System.getProperty("opsforge.metrics.path")),line,StandardOpenOption.CREATE,StandardOpenOption.APPEND);
        } catch(Exception error) {
            try {Files.writeString(Path.of(System.getProperty("opsforge.metrics.path")),"{\"sample_error\":\""+error.getClass().getName()+"\"}\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(IOException ignored) {throw new UncheckedIOException(ignored);}
        }
    }
    @Override protected void doGet(HttpServletRequest request,HttpServletResponse response)throws IOException {
        response.setContentType("application/json");response.setCharacterEncoding("UTF-8");
        if(request.getServletPath().equals("/ready")) {
            response.getWriter().print("{\"pid\":"+ProcessHandle.current().pid()+",\"server_version\":\""+serverVersion+"\",\"java_version\":\""+System.getProperty("java.version")+"\",\"tomcat\":\""+getServletContext().getServerInfo()+"\"}");return;
        }
        long start=System.nanoTime();boolean diagnosticGc="1".equals(request.getHeader("X-Diagnostic-GC"));
        if(diagnosticGc)System.gc();
        long borrowRequested=System.nanoTime(),borrowed=0,queried=0;String connectionId="null",error="";
        try(Connection connection=source.getConnection()) {
            borrowed=System.nanoTime();
            try(Statement statement=connection.createStatement();ResultSet result=statement.executeQuery("SELECT SLEEP(0.12), CONNECTION_ID()")) {
                if(!result.next()||result.getInt(1)!=0)throw new SQLException("actual SLEEP result");connectionId=String.valueOf(result.getLong(2));queried=System.nanoTime();
            }
        } catch(SQLException failure) {response.setStatus(503);error=failure.getClass().getSimpleName();}
        response.getWriter().print("{\"pid\":"+ProcessHandle.current().pid()+",\"borrow_wait_ms\":"+((borrowed==0?System.nanoTime():borrowed)-borrowRequested)/1e6
            +",\"query_ms\":"+(queried==0?0:(queried-borrowed)/1e6)+",\"service_ms\":"+(System.nanoTime()-start)/1e6
            +",\"diagnostic_gc_requested\":"+diagnosticGc+",\"pre_borrow_ms\":"+(borrowRequested-start)/1e6
            +",\"connection_id\":"+connectionId+",\"error\":\""+error+"\"}");
    }
    @Override public void destroy() {
        if(sampler!=null) {sampler.shutdown();try{if(!sampler.awaitTermination(2,TimeUnit.SECONDS)){sampler.shutdownNow();sampler.awaitTermination(2,TimeUnit.SECONDS);}}catch(InterruptedException error){Thread.currentThread().interrupt();}}
        if(source!=null)source.close(true);
    }
}

