import hashlib,json,os,pathlib
import decision

def encode(value):
    return json.dumps(value,ensure_ascii=False,separators=(',',':')).encode()

def seal(record,destination,now_ns,ttl_ns):
    if type(now_ns)is not int or type(ttl_ns)is not int or now_ns<0 or ttl_ns<=0:
        raise ValueError('nonnegative clock and positive integer retention required')
    root=pathlib.Path(destination);root.mkdir(mode=0o700)
    report=decision.report(record);raw=encode(record);public=encode(report)
    manifest={'raw_sha256':hashlib.sha256(raw).hexdigest(),'public_sha256':hashlib.sha256(public).hexdigest(),
              'raw_bytes':len(raw),'public_bytes':len(public),'created_ns':now_ns,'expires_ns':now_ns+ttl_ns,
              'owner_uid':os.getuid(),'raw_access':'owner_only','publication':'allowlisted_observations_without_raw_commands_tokens_stacks_or_profile'}
    for name,data in(('private.json',raw),('public.json',public),('manifest.json',encode(manifest))):
        fd=os.open(root/name,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)
        with os.fdopen(fd,'wb')as stream:stream.write(data)
    return manifest

def expire(destination,now_ns):
    if type(now_ns)is not int or now_ns<0:raise ValueError('integer clock required')
    root=pathlib.Path(destination);manifest=json.loads((root/'manifest.json').read_bytes())
    if now_ns<manifest['expires_ns']:return False
    for name in('private.json','public.json','manifest.json'):(root/name).unlink()
    root.rmdir()
    return True

