   self.validation=dict(command=command,returncode=validation.returncode,stdout=validation.stdout,stderr=validation.stderr)
   assert validation.returncode==0,'actual Envoy validation: '+json.dumps(self.validation)
   self.log=(self.root/'envoy.log').open('wb')
   self.command=[ENVOY,'--disable-hot-restart','--concurrency','1','--drain-time-s','0','--log-level','error','-c',str(path)]
   self.proc=subprocess.Popen(self.command,stdout=self.log,stderr=subprocess.STDOUT)
   self.boot=str(self.proc.pid)+':'+(pathlib.Path('/proc')/str(self.proc.pid)/'stat').read_text().split()[21]
   deadline=time.monotonic()+8
   while True:
    assert self.proc.poll()is None,'actual Envoy exited: '+(self.root/'envoy.log').read_text()
    try:
     if http_request('http://127.0.0.1:'+str(self.admin)+'/ready')[0]==200:break
    except(OSError,urllib.error.URLError):pass
    assert time.monotonic()<deadline,'actual Envoy readiness deadline';time.sleep(.03)
  except BaseException:self.close();raise
 def admin_json(self,path):
