    except subprocess.TimeoutExpired:self.proc.kill();self.proc.wait(timeout=3)
    assert self.proc.poll()is not None
   except BaseException as error:errors.append('process: '+repr(error))
  if self.log is not None:
   try:self.log.close()
   except BaseException as error:errors.append('log: '+repr(error))
