def plan(contract):
    keys=('max_body_bytes','upload_slots','executor_max_threads','control_threads_reserved','temporary_layers_per_upload','reserve_bytes','usable_bytes')
    for key in keys:
        if type(contract[key])is not int or contract[key]<0:raise ValueError('nonnegative integer capacity values required')
    if any(contract[key]<1 for key in('max_body_bytes','upload_slots','executor_max_threads','temporary_layers_per_upload')):raise ValueError('positive body/slots/threads/layers required')
    cost=contract['max_body_bytes']*contract['temporary_layers_per_upload']
    disk=max(0,(contract['usable_bytes']-contract['reserve_bytes'])//cost)
    admitted=min(contract['upload_slots'],max(0,contract['executor_max_threads']-contract['control_threads_reserved']),disk)
    return {'max_body_bytes':contract['max_body_bytes'],'configured_upload_slots':contract['upload_slots'],
            'effective_executor_threads':contract['executor_max_threads'],'control_threads_reserved':contract['control_threads_reserved'],
            'max_owned_disk_bytes_per_upload':cost,'reserved_bytes':contract['reserve_bytes'],
            'disk_limited_uploads':disk,'admission_limit':admitted,'all_requested_slots_fit':admitted==contract['upload_slots'],
            'do_not_increase_threads_as_only_fix':True}

