/** Owned lab fixture only. This is not a production upload implementation. */
public final class UploadServlet extends HttpServlet {
    static final long LIMIT=2L*1024*1024*1024;
    final Semaphore slots=new Semaphore(2);
    final AtomicInteger active=new AtomicInteger();
    Path temporary,metrics,events,closed;
    String downstream;
    ScheduledExecutorService sampler;

    static String quote(String value) {
        return "\""+value.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r")+"\"";
    }
    static long attribute(MBeanServer server,ObjectName name,String key)throws Exception {
        return ((Number)server.getAttribute(name,key)).longValue();
    }
    static synchronized void line(Path destination,String text)throws IOException {
        Files.writeString(destination,text+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);
    }
    @Override public void init()throws ServletException {
        try {
            temporary=Path.of(System.getProperty("opsforge.upload.temp"));
            metrics=Path.of(System.getProperty("opsforge.upload.metrics"));
            events=Path.of(System.getProperty("opsforge.upload.events"));
            closed=Path.of(System.getProperty("opsforge.upload.admissionClosed"));
            downstream=System.getProperty("opsforge.upload.downstream");
            Files.createDirectories(temporary);
            sampler=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"owned-upload-sampler");t.setDaemon(true);return t;});
            sampler.scheduleAtFixedRate(()->{
                try {
                    MBeanServer server=ManagementFactory.getPlatformMBeanServer();
                    ObjectName executor=new ObjectName("Catalina:type=Executor,name=owned");
                    long tempBytes=0,tempFiles=0;
                    try(var files=Files.list(temporary)) {
                        for(Path file:files.toList())try{tempBytes+=Files.size(file);tempFiles++;}catch(NoSuchFileException ignored){}
                    }
                    long direct=0,mapped=0;
                    for(BufferPoolMXBean pool:ManagementFactory.getPlatformMXBeans(BufferPoolMXBean.class)) {
                        if(pool.getName().equals("direct"))direct=pool.getMemoryUsed();
                        if(pool.getName().equals("mapped"))mapped=pool.getMemoryUsed();
                    }
                    line(metrics,"{\"nano\":"+System.nanoTime()+",\"upload_active\":"+active.get()
                        +",\"executor_active\":"+attribute(server,executor,"activeCount")
                        +",\"executor_queue\":"+attribute(server,executor,"queueSize")
                        +",\"executor_max_threads\":"+attribute(server,executor,"maxThreads")
                        +",\"jvm_threads\":"+ManagementFactory.getThreadMXBean().getThreadCount()
                        +",\"heap_used\":"+ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed()
                        +",\"direct_bytes\":"+direct+",\"mapped_bytes\":"+mapped
                        +",\"temporary_bytes\":"+tempBytes+",\"temporary_files\":"+tempFiles
                        +",\"filesystem_usable_bytes\":"+Files.getFileStore(temporary).getUsableSpace()
                        +",\"admission_closed\":"+Files.exists(closed)+"}");
                }catch(Exception error){
                    try{line(metrics,"{\"sample_error\":"+quote(error.toString())+"}");}catch(IOException ignored){}
                }
            },100,20,TimeUnit.MILLISECONDS);
        }catch(Exception error){throw new ServletException(error);}
    }
    @Override public void destroy(){if(sampler!=null)sampler.shutdownNow();}
    @Override protected void doGet(HttpServletRequest request,HttpServletResponse response)throws IOException {
