import calendar
import hashlib
import math
import time
from django.conf import settings
from django.core.cache import cache
from django.contrib.auth.models import Group
from djangosaml2.backends import Saml2Backend
from saml2.time_util import str_to_time

def receipt_key(issuer, assertion_id):
    return 'saml-receipt:' + hashlib.sha256((issuer + '\0' + assertion_id).encode()).hexdigest()

class ReceiptBackend(Saml2Backend):
    def is_authorized(self, attributes, attribute_mapping, idp_entityid, assertion_info, **kwargs):
        if idp_entityid != settings.OPSFORGE_TRUSTED_ISSUER:
            return False
        if attributes.get('uid') != ['lp-fixture']:
            return False
        if 'urn:opsforge:reader' not in attributes.get('eduPersonEntitlement', []):
            return False
        try:
            assertion_id = assertion_info['assertion_id']
            expiry = calendar.timegm(str_to_time(assertion_info['not_on_or_after']))
            ttl = math.ceil(expiry - time.time())
            if not isinstance(assertion_id, str) or not assertion_id or ttl <= 0:
                return False
            return bool(cache.add(receipt_key(idp_entityid, assertion_id),
                                  {'issuer': idp_entityid, 'assertion_id': assertion_id},
                                  timeout=ttl))
        except Exception:
            return False

    def _update_user(self, user, attributes, attribute_mapping, force_save=False):
        user = super()._update_user(user, attributes, attribute_mapping, force_save)
        group, _ = Group.objects.get_or_create(name='opsforge-reader')
        user.groups.add(group)
        return user

