"""Owned HTTP upstream fixture, with real HTTP/1 chunked entity decoding."""
import hashlib,http.server,json,threading,time


class Backend:
    def __init__(self):
        self.records=[];self.lock=threading.Lock();owner=self
        class Handler(http.server.BaseHTTPRequestHandler):
            protocol_version='HTTP/1.1'
            def log_message(self,*args):pass
            def setup(self):super().setup();self.connection.settimeout(3)
            def do_POST(self):
                digest=hashlib.sha256();total=0;started=time.monotonic()
                row=dict(path=self.path,owned_id=self.headers.get('X-Owned-Id'),content_length=self.headers.get('Content-Length'),transfer_encoding=self.headers.get('Transfer-Encoding'),complete=False,response_status=None,response_written=False)
                with owner.lock:owner.records.append(row)
                try:
                    def consume(size):
                        nonlocal total
                        while size:
                            part=self.rfile.read(min(size,65536))
                            if not part:raise EOFError('upstream request body incomplete')
                            digest.update(part);total+=len(part);size-=len(part)
                    if self.headers.get('Transfer-Encoding','').lower()=='chunked':
                        while True:
                            chunk_header=self.rfile.readline()
                            if not chunk_header:raise EOFError('upstream request entity ended before final chunk')
                            size=int(chunk_header.split(b';',1)[0],16)
                            if size==0:
                                while True:
                                    trailer=self.rfile.readline()
                                    if not trailer:raise EOFError('upstream request trailers incomplete')
                                    if trailer==b'\r\n':break
                                break
                            consume(size)
                            if self.rfile.read(2)!=b'\r\n':raise ValueError('invalid fixture request chunk delimiter')
                    else:consume(int(self.headers.get('Content-Length','0')))
                    row.update(bytes=total,sha256=digest.hexdigest(),complete=True,duration_seconds=time.monotonic()-started)
                    reply=json.dumps(row).encode()
                    self.send_response(200);self.send_header('Content-Length',str(len(reply)));self.send_header('Content-Type','application/json');self.send_header('Connection','close');self.end_headers();self.wfile.write(reply);row.update(response_status=200,response_written=True)
                except BaseException as error:
                    row.update(bytes=total,sha256=digest.hexdigest(),failure=type(error).__name__,duration_seconds=time.monotonic()-started)
                    self.close_connection=True
        self.server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler)
        self.thread=threading.Thread(target=self.server.serve_forever,name='owned-http-upstream')

    @property
    def port(self):return self.server.server_port

    def start(self):self.thread.start()

    def close(self):
        self.server.shutdown();self.server.server_close();self.thread.join(timeout=3)
        if self.thread.is_alive():raise AssertionError('owned upstream thread not joined')

