"""Minimal durable job and local charge ledger; no external payment integration."""
import contextlib
import hashlib
import json
import pathlib
import re
import sqlite3
import time
import uuid

@contextlib.contextmanager
def transaction(database):
    with contextlib.closing(sqlite3.connect(database,timeout=10)) as connection:
        connection.row_factory=sqlite3.Row
        connection.execute('PRAGMA foreign_keys=ON')
        connection.execute('BEGIN IMMEDIATE')
        try:
            yield connection
            connection.commit()
        except BaseException:
            connection.rollback()
            raise

def initialize(database):
    with transaction(database) as con:
        con.execute('CREATE TABLE IF NOT EXISTS control (name TEXT PRIMARY KEY,value TEXT NOT NULL)')
        con.execute("INSERT OR IGNORE INTO control VALUES ('accepting','yes')")
        con.execute('''CREATE TABLE IF NOT EXISTS jobs (
            id TEXT PRIMARY KEY,customer TEXT NOT NULL,idem_key TEXT NOT NULL,request_hash TEXT NOT NULL,
            month TEXT NOT NULL,state TEXT NOT NULL,owner TEXT,lease_until REAL,
            result_path TEXT,result_sha256 TEXT,created REAL NOT NULL,started REAL,finished REAL,
            max_runtime_seconds INTEGER NOT NULL DEFAULT 7200,
            UNIQUE(customer,idem_key))''')
        con.execute('''CREATE TABLE IF NOT EXISTS charges (
            event_id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),
            amount_minor INTEGER NOT NULL,created REAL NOT NULL)''')
        con.execute('''CREATE TABLE IF NOT EXISTS facts (
            id INTEGER PRIMARY KEY,customer TEXT NOT NULL,month TEXT NOT NULL,amount_minor INTEGER NOT NULL)''')

def _request(customer,key,parameters):
    if not isinstance(customer,str)or not customer or not isinstance(key,str)or not key:
        raise ValueError('customer and idempotency key required')
    if not isinstance(parameters,dict)or set(parameters)!={'month'}:
        raise ValueError('exact month parameter required')
    month=parameters['month']
    if not isinstance(month,str)or re.fullmatch(r'[0-9]{4}-(0[1-9]|1[0-2])',month)is None:
        raise ValueError('YYYY-MM required')
    encoded=json.dumps(parameters,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode('utf8')
    return month,hashlib.sha256(encoded).hexdigest()

def create(database,customer,key,parameters):
    month,digest=_request(customer,key,parameters)
    with transaction(database) as con:
        if con.execute("SELECT value FROM control WHERE name='accepting'").fetchone()[0]!='yes':
            raise RuntimeError('new jobs paused for charge reconciliation')
        existing=con.execute('SELECT * FROM jobs WHERE customer=? AND idem_key=?',(customer,key)).fetchone()
        if existing is not None:
            if existing['request_hash']!=digest:raise ValueError('same key with different parameters')
            return dict(existing)
        job_id=uuid.uuid4().hex
        con.execute('INSERT INTO jobs(id,customer,idem_key,request_hash,month,state,created) VALUES (?,?,?,?,?,?,?)',
                    (job_id,customer,key,digest,month,'queued',time.time()))
        return dict(con.execute('SELECT * FROM jobs WHERE id=?',(job_id,)).fetchone())

def get(database,customer,job_id):
    with transaction(database) as con:
        row=con.execute('SELECT * FROM jobs WHERE customer=? AND id=?',(customer,job_id)).fetchone()
        if row is None:raise KeyError(job_id)
        return dict(row)

def cancel(database,customer,job_id):
    with transaction(database) as con:
        row=con.execute('SELECT * FROM jobs WHERE customer=? AND id=?',(customer,job_id)).fetchone()
        if row is None:raise KeyError(job_id)
        if row['state']in ('queued','running','succeeded'):
            con.execute("UPDATE jobs SET state='cancel_requested' WHERE id=?",(job_id,))
        return dict(con.execute('SELECT * FROM jobs WHERE id=?',(job_id,)).fetchone())

def claim(database,owner,lease_seconds=10):
    if not isinstance(owner,str)or re.fullmatch('[A-Za-z0-9_-]{1,64}',owner)is None:
        raise ValueError('owned executor token required')
    if type(lease_seconds)not in (int,float)or not 0<lease_seconds<=60:
        raise ValueError('positive fixture lease up to60 seconds')
    with transaction(database) as con:
        now=time.time()
        con.execute("UPDATE jobs SET state='failed',finished=?,owner=NULL,lease_until=NULL WHERE state IN ('running','cancel_requested') AND started IS NOT NULL AND started+max_runtime_seconds<=?",(now,now))
        con.execute("UPDATE jobs SET state='cancelled',owner=NULL,lease_until=NULL,finished=? WHERE state='cancel_requested'",(now,))
        row=con.execute("SELECT * FROM jobs WHERE state='queued' OR (state='running' AND lease_until<=?) ORDER BY created,id LIMIT 1",(now,)).fetchone()
        if row is None:return None
        con.execute("UPDATE jobs SET state='running',owner=?,lease_until=?,started=COALESCE(started,?) WHERE id=?",(owner,now+lease_seconds,now,row['id']))
        return dict(con.execute('SELECT * FROM jobs WHERE id=?',(row['id'],)).fetchone())

def heartbeat(database,job_id,owner,lease_seconds=10):
    if type(lease_seconds)not in (int,float)or not 0<lease_seconds<=60:raise ValueError('lease')
    with transaction(database) as con:
        return con.execute("UPDATE jobs SET lease_until=? WHERE id=? AND owner=? AND state='running'",(time.time()+lease_seconds,job_id,owner)).rowcount==1

def finish(database,job_id,owner,result_file,result_sha256):
    path=pathlib.Path(result_file)
    if path.is_symlink()or not path.is_file()or hashlib.sha256(path.read_bytes()).hexdigest()!=result_sha256:
