import hashlib,hmac

def cohort(subject,secret):
    return 'experiment' if hmac.new(secret.encode(),subject.encode(),hashlib.sha256).digest()[0]&1 else 'control'

def decision(now,started,maximum,last_heartbeat,stopped,scope_proven,stop_proven):
    if not scope_proven:return {'enabled':False,'reason':'scope_unproven'}
    if not stop_proven:return {'enabled':False,'reason':'stop_unproven'}
    if stopped:return {'enabled':False,'reason':'manual_stop'}
    if now-started>=maximum:return {'enabled':False,'reason':'expired'}
    if now-last_heartbeat>500_000_000:return {'enabled':False,'reason':'control_lost'}
    return {'enabled':True,'reason':'active'}

