def audit(record):
    logs={row['request_id']:row for row in record['actual_access_logs']}
    endpoints={row['port']:row for row in record['trusted_namespace_endpoints']}
    counts={'injected_aborts':0,'injected_delays':0,'natural_errors':0,'injected_cancellations':0}
    outside=[]
    for row in record['traffic']:
        entry=logs[row['id']];flags=set(entry['flags'].split(','));injected=bool(flags&{'FI','DI'})
        counts['injected_aborts']+=int('FI'in flags)
        counts['injected_delays']+=int('DI'in flags)
        counts['injected_cancellations']+=int(injected and row['status']is None)
        counts['natural_errors']+=int(not injected and row['status']is not None and row['status']>=500)
        endpoint=endpoints[row['port']]
        if injected and not(endpoint['tenant']=='tenant-a'and endpoint['group']=='experiment'and row['path'].startswith('/eligible/')):outside.append(row['id'])
    final={}
    for event in record['actual_watchdog_events']:final[event['command']['serial']]=event['decision']['reason']
    retry=record['client_retries']
    return dict(actual_attempts=len(record['traffic']),**counts,out_of_scope=sorted(outside),retry_logical=retry['logical_requests'],retry_attempts=len(retry['actual_attempts']),retry_amplification=len(retry['actual_attempts'])/retry['logical_requests'],retry_upstream=len(retry['actual_upstream_events']),final_decisions=final)

