package rotationlab

import (
 "context"
 "database/sql"
 "encoding/json"
 "errors"
 "io"
 "os"
 "path/filepath"
 "strings"
 "time"
 mysql "github.com/go-sql-driver/mysql"
)

type SecretConfig struct { Version string `json:"version"`; User string `json:"user"`; Password string `json:"password"`; Schema string `json:"schema"`; Socket string `json:"socket"` }
type Consumer struct { Name string; Environment string; Schema string; LoadMode string; Version string; Verified bool }

func LoadSecret(path string) (SecretConfig,error) {
 var c SecretConfig
 info,err:=os.Lstat(path);if err!=nil{return c,err}
 if !info.Mode().IsRegular()||info.Size()>8192||info.Mode().Perm()&0077!=0{return c,errors.New("private regular secret material required")}
 f,err:=os.Open(path);if err!=nil{return c,err};defer f.Close()
 decoder:=json.NewDecoder(io.LimitReader(f,8193));decoder.DisallowUnknownFields()
 if err=decoder.Decode(&c);err!=nil{return c,err}
 var extra interface{};if decoder.Decode(&extra)!=io.EOF{return c,errors.New("single secret config required")}
 if strings.TrimSpace(c.Version)==""||c.User==""||c.Password==""||c.Schema==""||c.Socket==""{return c,errors.New("complete versioned secret required")}
 return c,nil
}

func ReadyToRetire(inventory []Consumer, version, decisionOwner string) error {
 if strings.TrimSpace(decisionOwner)==""||strings.TrimSpace(version)==""||len(inventory)==0{return errors.New("decision owner, version and complete consumer inventory required")}
 seen:=map[string]bool{}
 for _,c:=range inventory {
  if c.Name==""||c.Environment==""||c.Schema==""||c.LoadMode==""||seen[c.Name] {return errors.New("incomplete or duplicate consumer")}
  seen[c.Name]=true
  if c.Version!=version||!c.Verified{return errors.New("consumer has not authenticated with current version")}
 }
 return nil
}

// ConnectConsumer uses the real standard database/sql connection and official MySQL driver.
// Caller owns the returned connection pool and must close it.
func ConnectConsumer(ctx context.Context,c SecretConfig) (*sql.DB,error) {
 if c.User==""||c.Password==""||c.Schema==""||c.Socket==""||strings.TrimSpace(c.Version)==""{return nil,errors.New("complete versioned consumer config required")}
 cfg:=mysql.NewConfig();cfg.User=c.User;cfg.Passwd=c.Password;cfg.Net="unix";cfg.Addr=c.Socket;cfg.DBName=c.Schema;cfg.Timeout=2*time.Second;cfg.ReadTimeout=2*time.Second;cfg.WriteTimeout=2*time.Second
 db,err:=sql.Open("mysql",cfg.FormatDSN());if err!=nil{return nil,err};db.SetMaxOpenConns(1);db.SetMaxIdleConns(1)
 if err=db.PingContext(ctx);err!=nil{db.Close();return nil,err}
 return db,nil
}

type ConsumerProbe struct { Database string `json:"database"`; Count int64 `json:"count"`; Total int64 `json:"total"` }
func ProbeConsumer(ctx context.Context,db *sql.DB) (ConsumerProbe,error) {
 var result ConsumerProbe
 if err:=db.QueryRowContext(ctx,"SELECT DATABASE()").Scan(&result.Database);err!=nil{return result,err}
 err:=db.QueryRowContext(ctx,"SELECT COUNT(*),COALESCE(SUM(`value`),0) FROM owned_records").Scan(&result.Count,&result.Total)
 return result,err
}

// PublishSecret is the controlled file distribution mechanism for this local project.
// It never changes the process/default identity or any global client configuration.
func PublishSecret(path string,c SecretConfig) error {
 if strings.TrimSpace(c.Version)==""||c.User==""||c.Password==""||c.Schema==""||c.Socket==""{return errors.New("complete secret config required")}
 directory:=filepath.Dir(path);info,err:=os.Stat(directory);if err!=nil{return err}
 if !info.IsDir()||info.Mode().Perm()&0077!=0{return errors.New("owned private distribution directory required")}
 encoded,err:=json.Marshal(c);if err!=nil{return err};file,err:=os.CreateTemp(directory,".owned-secret-");if err!=nil{return err};temporary:=file.Name()
 defer func(){file.Close();os.Remove(temporary)}()
 if err=file.Chmod(0600);err!=nil{return err}
 if _,err=file.Write(encoded);err!=nil{return err};if err=file.Sync();err!=nil{return err};if err=file.Close();err!=nil{return err}
 if err=os.Rename(temporary,path);err!=nil{return err};parent,err:=os.Open(directory);if err!=nil{return err};defer parent.Close();return parent.Sync()
}

