package rotationlab

import (
 "context"
 "database/sql"
 "errors"
 "regexp"
)

var userPattern=regexp.MustCompile(`^[a-z][a-z0-9_]{1,29}$`)
var passwordPattern=regexp.MustCompile(`^[A-Za-z0-9_-]{24,128}$`)

func ownedAccount(user string) (string,error) {
 if !userPattern.MatchString(user){return "",errors.New("bounded owned test identity required")}
 return "'"+user+"'@'localhost'",nil
}

func EstablishOverlap(ctx context.Context, admin *sql.DB, user,newPassword string) error {
 account,err:=ownedAccount(user);if err!=nil{return err}
 if !passwordPattern.MatchString(newPassword){return errors.New("generated owned test secret required")}
 _,err=admin.ExecContext(ctx,"ALTER USER "+account+" IDENTIFIED BY '"+newPassword+"' RETAIN CURRENT PASSWORD")
 return err
}

func RetirePrevious(ctx context.Context,admin *sql.DB,user,version,owner string,inventory []Consumer) error {
 if err:=ReadyToRetire(inventory,version,owner);err!=nil{return err}
 account,err:=ownedAccount(user);if err!=nil{return err}
 _,err=admin.ExecContext(ctx,"ALTER USER "+account+" DISCARD OLD PASSWORD")
 return err
}

