from django.conf import settings
from djangosaml2.backends import Saml2Backend
from django.contrib.sessions.models import Session
from django.core.exceptions import PermissionDenied
from django.http import Http404

def get_object_for_user(user,objects,object_id,action='read'):
    if not user.is_authenticated:raise PermissionDenied('login required')
    try:item=objects.get(pk=object_id)
    except objects.model.DoesNotExist:raise Http404('owned object missing')
    if not user.groups.filter(name='owned-tenant:'+item.tenant+':reader').exists():raise PermissionDenied('current tenant membership required')
    if action not in ('read','write'):raise PermissionDenied('unsupported operation')
    if action=='write'and not user.groups.filter(name='owned-tenant:'+item.tenant+':writer').exists():raise PermissionDenied('current writer membership required')
    return item

def revoke_sessions(user):
    if user.pk is None:raise ValueError('persisted owned user required')
    removed=[]
    for session in Session.objects.iterator():
        if session.get_decoded().get('_auth_user_id')==str(user.pk):
            removed.append(session.session_key);session.delete()
    return len(removed)

class TenantBackend(Saml2Backend):
    def is_authorized(self,attributes,attribute_mapping,idp_entityid,assertion_info,**kwargs):
        if idp_entityid!=settings.OPSFORGE_TRUSTED_ISSUER:return False
        uid=attributes.get('uid',[]);tenant=attributes.get('tenant',[])
        return len(uid)==1 and uid[0]in settings.OPSFORGE_FIXTURE_USERS and len(tenant)==1 and settings.OPSFORGE_FIXTURE_USERS[uid[0]]==tenant[0]and tenant[0]in settings.OPSFORGE_TENANTS and attributes.get('eduPersonEntitlement')==['urn:opsforge:reader']

    # Business tenant memberships are provisioned/revoked in the local application DB.
    # A fresh SSO login must not implicitly recreate a role removed by that authority.

