import json
import sys
from evidence import assess

def decide(row):
    if not row['business_healthy']:
        return 'HOLD_BACKEND'
    if not row['management_connected']:
        return 'HOLD_CONTROL_PLANE'
    if row['discovery_state'] == 'NACK':
        return 'HOLD_REJECTED_UPDATE'
    return 'READY'

def build_report(bundle):
    return {'phases': [{**row, 'decision': decide(row)} for row in assess(bundle)],
            'scope': 'owned Envoy singleton SotW RDS; not Istiod or global atomicity'}

if __name__ == '__main__':
    with open(sys.argv[1], encoding='utf8') as stream:
        print(json.dumps(build_report(json.load(stream))))

