   path=self.root/'bootstrap.json';path.write_text(json.dumps(replace(json.loads(template))))
   command=[ENVOY,'--mode','validate','-c',str(path),'--log-level','debug']
   validation=subprocess.run(command,capture_output=True,text=True,timeout=10)
   self.validation=dict(command=command,returncode=validation.returncode,stdout=validation.stdout,stderr=validation.stderr)
   if validation.returncode<0:raise RuntimeError('NATIVE_EXECUTION_UNVERIFIED: Envoy bootstrap validator was terminated')
   assert validation.returncode==0,'actual Envoy rejected the supplied bootstrap; complete original validation attached to native evidence'
   self.log=(self.root/'envoy.log').open('wb')
   self.command=[ENVOY,'--disable-hot-restart','--concurrency','1','--drain-time-s','3','--log-level','debug','-c',str(path)]
   self.proc=subprocess.Popen(self.command,stdout=self.log,stderr=subprocess.STDOUT)
   self.boot=str(self.proc.pid)+':'+(pathlib.Path('/proc')/str(self.proc.pid)/'stat').read_text().split()[21]
   deadline=time.monotonic()+8
