package main

import (
	"crypto"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"math/big"
	"os"
	"time"
)

func encode(value any) string {
	raw, err := json.Marshal(value)
	if err != nil {
		panic(err)
	}
	return base64.RawURLEncoding.EncodeToString(raw)
}

func sign(key *rsa.PrivateKey, kid, issuer, audience, role string, expiration int64) string {
	message := encode(map[string]any{"alg": "RS256", "typ": "JWT", "kid": kid}) + "." +
		encode(map[string]any{"iss": issuer, "aud": audience, "sub": "owned-test-client", "role": role,
			"iat": time.Now().Unix() - 7200, "nbf": time.Now().Unix() - 7200, "exp": expiration})
	digest := sha256.Sum256([]byte(message))
	signature, err := rsa.SignPKCS1v15(rand.Reader, key, crypto.SHA256, digest[:])
	if err != nil {
		panic(err)
	}
	return message + "." + base64.RawURLEncoding.EncodeToString(signature)
}

func main() {
	if os.Getuid() != 1000 || os.Geteuid() != 1000 {
		panic("fixed student UID1000 required")
	}
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		panic(err)
	}
	other, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		panic(err)
	}
	var suffix [8]byte
	if _, err = rand.Read(suffix[:]); err != nil {
		panic(err)
	}
	kid := "owned-" + hex.EncodeToString(suffix[:])
	issuer := "https://issuer.owned.test/" + kid
	audience := "owned-version-gate"
	expiration := time.Now().Unix() + 3600
	jwk := map[string]any{"kty": "RSA", "kid": kid, "alg": "RS256", "use": "sig",
		"n": base64.RawURLEncoding.EncodeToString(key.PublicKey.N.Bytes()),
		"e": base64.RawURLEncoding.EncodeToString(big.NewInt(int64(key.PublicKey.E)).Bytes())}
	result := map[string]any{"uid": os.Getuid(), "euid": os.Geteuid(), "issuer": issuer, "audience": audience,
		"jwks": map[string]any{"keys": []any{jwk}}, "private_key_never_output": true,
		"tokens": map[string]string{
			"reader": sign(key, kid, issuer, audience, "reader", expiration),
			"wrong_role": sign(key, kid, issuer, audience, "other", expiration),
			"expired": sign(key, kid, issuer, audience, "reader", time.Now().Unix()-3600),
			"wrong_signature": sign(other, kid, issuer, audience, "reader", expiration),
		}}
	if err := json.NewEncoder(os.Stdout).Encode(result); err != nil {
		panic(err)
	}
}

